import sys

sys.setrecursionlimit(300000)


def read_lines():
    return [ln.strip() for ln in sys.stdin.read().split('\n') if ln.strip() != '']


class TNode:
    def __init__(self, v):
        self.val = v
        self.left = None
        self.right = None


def build_tree(tokens):
    it = iter(tokens)
    first = next(it, -1)
    if first == -1:
        return None
    root = TNode(first)
    q = [root]
    for node in q:
        l = next(it, -1)
        if l != -1:
            node.left = TNode(l)
            q.append(node.left)
        r = next(it, -1)
        if r != -1:
            node.right = TNode(r)
            q.append(node.right)
    return root


def height(root):
    if root is None:
        return 0
    return 1 + max(height(root.left), height(root.right))


def diameter(root):
    if root is None:
        return 0
    through_root = height(root.left) + height(root.right) + 1
    return max(through_root, diameter(root.left), diameter(root.right))


def main():
    lines = read_lines()
    tokens = list(map(int, lines[1].split()))
    print(diameter(build_tree(tokens)))


main()

